def tarih(metin):
    """GG.AA.YYYY" biçimindeki tarihi date nesnesine çevirir."""
    a, g, y = metin.strip().split(".")
    # a=gün, g=ay, y=yıl (GG.AA.YYYY formatı)
    return date(int(y), int(g), int(a))
